effect.shader:
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }

void main() {
    vec2 uv = acScreenNorm;
    float t = acTime * speed;

    // warp horizontal animado
    float w = sin(uv.y * 80.0 + t * 3.0) * warp + sin(uv.y * 12.0 - t) * warp * 0.5;
    vec2 uvW = vec2(uv.x + w, uv.y);

    // chroma shift
    float dx = chroma / acResolution.x;
    float r = texture(inputImg, uvW + vec2(dx, 0.0)).r;
    vec4 g = texture(inputImg, uvW);
    float b = texture(inputImg, uvW - vec2(dx, 0.0)).b;
    vec3 col = vec3(r, g.g, b);

    // scanlines
    float sl = 1.0 - scanAmount * 0.5 * (0.5 + 0.5 * sin(uv.y * acResolution.y * 3.14159));
    col *= sl;

    // grão
    float n = hash(uv * acResolution + fract(t));
    col += (n - 0.5) * grain;

    // leve saturação-queda para vibe de fita
    float L = dot(col, vec3(0.2126, 0.7152, 0.0722));
    col = mix(vec3(L), col, 0.85);

    fragColor = vec4(clamp(col, 0.0, 1.0), g.a);
}
